import os, shutil, sys, time

RUTA = sys.argv[1] if len(sys.argv) > 1 else "/opt/chivato/bot.py"
carpeta = os.path.join(os.path.dirname(os.path.abspath(RUTA)), "miniapp")
idx = os.path.join(carpeta, "index.html")
if not os.path.isdir(carpeta):
    print("ABORTO: no existe la carpeta miniapp; aplica antes parche_miniapp.py, 2 y 3"); sys.exit(1)

HTML = '<!doctype html>\n<html lang="es"><head><meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">\n<title>Chivato de Ofertas</title>\n<script src="https://telegram.org/js/telegram-web-app.js"></script>\n<link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Rajdhani:wght@500;600;700&family=Orbitron:wght@700;900&display=swap" rel="stylesheet">\n<style>\n:root{--bg:#05030f;--bg2:#12062b;--card:#0b0a26;--card2:#120d34;--cy:#00ebff;--mg:#ff28c8;--vd:#50ff96;--rj:#ff325a;--mut:#8f9bd1;--tx:#fff;--line:rgba(0,235,255,.5);--glow:0 0 14px rgba(0,235,255,.28)}\n*{box-sizing:border-box;margin:0;-webkit-tap-highlight-color:transparent}\nhtml,body{background:var(--bg)}\nbody{background:linear-gradient(180deg,var(--bg),var(--bg2));color:var(--tx);font:600 16px/1.35 Rajdhani,system-ui,-apple-system,Segoe UI,Roboto,sans-serif;min-height:100vh;padding:0 16px 100px;overflow-x:hidden}\nbody:before{content:"";position:fixed;left:-60%;right:-60%;bottom:0;height:52vh;z-index:-1;pointer-events:none;background:linear-gradient(rgba(5,3,15,0),rgba(110,20,190,.4)),repeating-linear-gradient(90deg,rgba(255,40,200,.38) 0 1px,transparent 1px 64px),repeating-linear-gradient(0deg,rgba(255,40,200,.38) 0 1px,transparent 1px 44px);transform:perspective(420px) rotateX(62deg);transform-origin:50% 100%;animation:grid 2.4s linear infinite}\n@keyframes grid{to{background-position:0 0,0 0,0 44px}}\nbody:after{content:"";position:fixed;inset:0;z-index:9;pointer-events:none;background:repeating-linear-gradient(0deg,rgba(0,0,0,.16) 0 1px,transparent 1px 3px)}\nheader{padding:16px 0 8px;display:flex;align-items:center;justify-content:space-between}\nh1{font:900 21px/1.1 Orbitron,Rajdhani,system-ui,sans-serif;letter-spacing:.5px;text-shadow:0 0 12px rgba(0,235,255,.7),0 0 2px #fff;animation:gl 6s infinite}\nh1 span{color:var(--mg);text-shadow:0 0 12px rgba(255,40,200,.8)}\n@keyframes gl{0%,92%,100%{transform:none}93%{transform:translateX(-2px);text-shadow:3px 0 var(--mg),-3px 0 var(--cy)}95%{transform:translateX(2px);text-shadow:-3px 0 var(--mg),3px 0 var(--cy)}97%{transform:none}}\n.live{display:flex;align-items:center;gap:7px;color:var(--mut);font-size:14px;margin-top:5px;letter-spacing:.6px;text-transform:uppercase}\n.dot{width:8px;height:8px;border-radius:50%;background:var(--vd);box-shadow:0 0 8px var(--vd);animation:pulse 1.6s infinite}\n@keyframes pulse{50%{opacity:.35}}\n.gear{background:var(--card);border:1px solid var(--mg);color:var(--mg);border-radius:12px;width:40px;height:40px;font-size:18px;box-shadow:0 0 12px rgba(255,40,200,.35)}\n.tabs{position:fixed;left:10px;right:10px;bottom:calc(10px + env(safe-area-inset-bottom));display:flex;background:rgba(8,5,28,.88);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);border:1px solid var(--mg);border-radius:20px;padding:6px;gap:2px;z-index:5;box-shadow:0 0 18px rgba(255,40,200,.35),inset 0 0 12px rgba(255,40,200,.12)}\n.tabs button{flex:1;background:none;border:0;color:var(--mut);font:700 11px Rajdhani,system-ui;letter-spacing:.8px;text-transform:uppercase;padding:7px 2px 6px;border-radius:14px;display:flex;flex-direction:column;align-items:center;gap:3px;transition:.2s}\n.tabs svg{width:22px;height:22px;stroke:currentColor;fill:none;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}\n.tabs button.on{color:var(--cy);background:rgba(0,235,255,.1);box-shadow:inset 0 0 0 1px rgba(0,235,255,.55),0 0 12px rgba(0,235,255,.3);text-shadow:0 0 8px var(--cy)}\nsection{animation:fade .35s ease}\n@keyframes fade{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}\n.chips{display:flex;gap:8px;overflow-x:auto;padding:8px 0;scrollbar-width:none}\n.chip{flex:none;background:rgba(11,10,38,.9);border:1px solid rgba(0,235,255,.4);color:var(--tx);border-radius:10px;padding:6px 14px;font:700 15px Rajdhani,system-ui;letter-spacing:.5px;transition:.15s}\n.chip.on{background:var(--cy);border-color:var(--cy);color:#04101a;box-shadow:0 0 14px rgba(0,235,255,.6)}\ninput.q,select.q{width:100%;background:rgba(11,10,38,.92);border:1px solid rgba(0,235,255,.45);border-radius:12px;color:var(--tx);padding:11px 14px;font:600 17px Rajdhani,system-ui;margin-bottom:6px;outline:none}\ninput.q:focus,select.q:focus{border-color:var(--cy);box-shadow:var(--glow)}\n.hero{position:relative;overflow:hidden;border-radius:20px;padding:18px;margin:10px 0 4px;background:linear-gradient(140deg,#1a0838,#08123a);border:1px solid var(--mg);box-shadow:0 0 22px rgba(255,40,200,.45),inset 0 0 26px rgba(255,40,200,.14)}\n.hero small{font:900 11px Orbitron,Rajdhani,sans-serif;letter-spacing:1.6px;color:var(--cy);text-shadow:0 0 8px var(--cy)}\n.hero .tt{color:#fff;font-size:19px;margin-top:6px;-webkit-line-clamp:2}\n.hero .big{font:900 34px Orbitron,Rajdhani,sans-serif;margin-top:8px;color:var(--vd);text-shadow:0 0 14px rgba(80,255,150,.7)}.hero .big s{font:600 16px Rajdhani,sans-serif;color:var(--mut);margin-left:8px;text-shadow:none}\n.hero .btn{margin-top:12px}\n.hero .bg{position:absolute;right:14px;top:14px;font:900 30px Orbitron,Rajdhani,sans-serif;color:var(--rj);text-shadow:0 0 14px rgba(255,50,90,.9)}\n.card{position:relative;background:linear-gradient(160deg,var(--card),var(--card2));border:1px solid var(--line);border-radius:18px;padding:15px;margin:12px 0;box-shadow:var(--glow),inset 0 0 16px rgba(0,235,255,.06);animation:fade .4s ease both}\n.tt{font-weight:700;font-size:17px;line-height:1.2;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;padding-right:36px}\n.row{display:flex;align-items:center;gap:12px;margin-top:10px}\n.now{font:900 27px Orbitron,Rajdhani,sans-serif;color:var(--vd);text-shadow:0 0 12px rgba(80,255,150,.6);letter-spacing:-.5px}\n.old{color:var(--mut);text-decoration:line-through;text-decoration-color:var(--rj);font-size:16px}\n.pct{margin-left:auto;background:rgba(255,50,90,.14);border:1.5px solid var(--rj);color:#fff;border-radius:12px;padding:5px 12px;font:900 17px Orbitron,Rajdhani,sans-serif;box-shadow:0 0 14px rgba(255,50,90,.6),inset 0 0 10px rgba(255,50,90,.3);text-shadow:0 0 8px var(--rj)}\n.bar{height:8px;border-radius:3px;background:repeating-linear-gradient(90deg,rgba(255,255,255,.08) 0 8px,transparent 8px 11px);margin-top:12px;overflow:hidden}\n.bar i{display:block;height:100%;background:linear-gradient(90deg,var(--cy),var(--mg));-webkit-mask:repeating-linear-gradient(90deg,#000 0 8px,transparent 8px 11px);mask:repeating-linear-gradient(90deg,#000 0 8px,transparent 8px 11px);box-shadow:0 0 10px var(--cy)}\n.meta{color:var(--mut);font-size:14px;margin-top:9px;display:flex;flex-wrap:wrap;gap:6px;align-items:center}\n.tag{border-radius:6px;font:800 11px Rajdhani,sans-serif;letter-spacing:.8px;text-transform:uppercase;padding:3px 8px;border:1px solid rgba(143,155,209,.5);background:rgba(143,155,209,.08);color:var(--mut)}\n.tag.hot{background:rgba(255,50,90,.14);border-color:var(--rj);color:#ff8aa0;box-shadow:0 0 8px rgba(255,50,90,.4)}\n.tag.new{background:rgba(80,255,150,.12);border-color:var(--vd);color:var(--vd);animation:blink 1.4s infinite;box-shadow:0 0 8px rgba(80,255,150,.4)}\n@keyframes blink{50%{opacity:.5}}\n.sv{color:var(--vd);font-weight:700}\n.two{display:flex;gap:8px;margin-top:12px}.two .btn{margin-top:0}\n.btn{display:block;width:100%;background:linear-gradient(90deg,var(--mg),#ff5a3c);color:#fff;border:0;border-radius:12px;padding:12px;font:800 16px Rajdhani,system-ui;letter-spacing:1px;text-transform:uppercase;box-shadow:0 0 16px rgba(255,40,200,.55);text-shadow:0 0 6px rgba(0,0,0,.4);transition:transform .1s}\n.btn:active{transform:scale(.97)}\n.btn.sec{background:rgba(0,235,255,.08);color:var(--cy);border:1px solid var(--cy);width:auto;flex:none;padding:12px 16px;box-shadow:0 0 10px rgba(0,235,255,.35);text-shadow:0 0 6px var(--cy)}\n.hero .btn{background:linear-gradient(90deg,var(--cy),#6a7bff);color:#03101a;text-shadow:none;box-shadow:0 0 18px rgba(0,235,255,.6)}\n.hb{position:absolute;top:9px;right:10px;background:none;border:0;color:var(--mut);font-size:25px;padding:4px 6px;transition:transform .2s}\n.hb.on{color:var(--mg);text-shadow:0 0 10px var(--mg)}.hb.pop{animation:pop .4s}\n@keyframes pop{40%{transform:scale(1.5)}}\n.empty{color:var(--mut);text-align:center;padding:38px 10px;letter-spacing:.4px}\n.sk{height:150px;border-radius:18px;margin:12px 0;border:1px solid rgba(0,235,255,.2);background:linear-gradient(100deg,rgba(0,235,255,.03) 30%,rgba(0,235,255,.14) 50%,rgba(0,235,255,.03) 70%);background-size:300% 100%;animation:sh 1.3s infinite}\n@keyframes sh{from{background-position:100% 0}to{background-position:-100% 0}}\n.legal{color:#7e89bd;font-size:12.5px;margin:18px 0 6px;line-height:1.4}\n.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:12px 0}\n.st{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:14px;box-shadow:var(--glow)}\n.st b{display:block;font:900 24px Orbitron,Rajdhani,sans-serif;color:var(--cy);text-shadow:0 0 10px var(--cy)}.st span{color:var(--mut);font-size:14px}\n.sw{display:flex;align-items:center;justify-content:space-between;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:13px 14px;margin:8px 0}\n.sw button{width:52px;height:30px;border-radius:999px;border:1px solid var(--mut);background:#16143a;position:relative}\n.sw button:after{content:"";position:absolute;top:3px;left:3px;width:22px;height:22px;border-radius:50%;background:var(--mut);transition:.2s}\n.sw button.on{background:rgba(80,255,150,.18);border-color:var(--vd);box-shadow:0 0 10px rgba(80,255,150,.5)}.sw button.on:after{left:25px;background:var(--vd);box-shadow:0 0 8px var(--vd)}\n.al{display:flex;align-items:center;justify-content:space-between;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:12px 14px;margin:8px 0;gap:10px}\n.al button{background:none;border:0;color:var(--rj);font-size:20px;text-shadow:0 0 8px var(--rj)}\n.info{color:var(--mut);font-size:15px;margin:6px 0 10px}\nh2{font:900 15px Orbitron,Rajdhani,sans-serif;letter-spacing:1px;margin:18px 0 6px;color:var(--cy);text-shadow:0 0 10px rgba(0,235,255,.7);text-transform:uppercase}\n.feed{height:calc(100dvh - 190px);min-height:420px;overflow-y:auto;scroll-snap-type:y mandatory;scrollbar-width:none;margin:8px -4px 0;border-radius:20px}\n.feed::-webkit-scrollbar{display:none}\n.vs{height:100%;scroll-snap-align:start;scroll-snap-stop:always;padding:4px;display:flex;flex-direction:column}\n.vbox{position:relative;border-radius:18px;overflow:hidden;background:#000;width:100%;border:1px solid var(--cy);box-shadow:0 0 22px rgba(0,235,255,.45)}\n.vbox video{width:100%;height:auto;max-height:calc(100dvh - 400px);object-fit:contain;margin:0 auto;display:block}\n.vbox .pc{position:absolute;left:12px;top:12px;background:rgba(255,50,90,.2);border:1.5px solid var(--rj);border-radius:10px;padding:4px 11px;font:900 16px Orbitron,Rajdhani,sans-serif;box-shadow:0 0 12px rgba(255,50,90,.7)}\n.vinfo{padding:12px 4px 0}.vinfo .tt{padding:0;font-size:18px}\n.hide{display:none!important}\n@media (prefers-reduced-motion:reduce){*,*:before{animation:none!important}}\n</style></head><body>\n<header><div><h1>Chivato <span>de Ofertas</span></h1><div class="live"><i class="dot"></i><span id="sub">Buscando ofertas…</span></div></div><button class="gear hide" id="adbtn" aria-label="Admin">⚙</button></header>\n<section id="t-of"><div id="hero"></div><input class="q" id="q" placeholder="Buscar producto…" inputmode="search">\n<div class="chips" id="chips"></div><div class="chips" id="cats"></div><select class="q" id="ord"><option value="r">Más recientes</option><option value="d">Mayor descuento</option><option value="p">Menor precio</option></select><div id="list"><div class="sk"></div><div class="sk"></div></div></section>\n<section id="t-vd" class="hide"><div class="feed" id="feed"></div></section>\n<section id="t-fv" class="hide"><h2>Mis favoritos</h2><div id="favs"></div></section>\n<section id="t-al" class="hide"><h2>Mis alertas</h2><div class="info">Te aviso por el chat del bot cuando salga una oferta que coincida. Máximo 5.</div><input class="q" id="aq" placeholder="Producto (ej. auriculares)" maxlength="40"><select class="q" id="am"><option value="0">Cualquier descuento</option><option value="20">20% o más</option><option value="30">30% o más</option><option value="50">50% o más</option><option value="70">70% o más</option></select><button class="btn" id="aadd">Crear alerta</button><div id="als" style="margin-top:12px"></div></section>\n<section id="t-top" class="hide"><h2>Mayor descuento (24 h)</h2><div id="top"></div><h2>Más pulsadas en la app</h2><div id="clk"></div></section>\n<section id="t-ad" class="hide"><h2>Resumen</h2><div class="grid" id="stats"></div><h2>Funciones</h2><div id="sws"></div></section>\n<div class="legal" id="legal">Como afiliado de Amazon obtengo ingresos por las compras adscritas. Los precios corresponden al momento del aviso y pueden cambiar.</div>\n<nav class="tabs">\n<button class="on" data-t="of"><svg viewBox="0 0 24 24"><path d="M3 12l9-8 9 8"/><path d="M5 10v10h14V10"/></svg>Ofertas</button>\n<button data-t="vd"><svg viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="14" rx="3"/><path d="M10 9l5 3-5 3z"/></svg>Vídeos</button>\n<button data-t="fv"><svg viewBox="0 0 24 24"><path d="M12 20s-7-4.4-7-10a4 4 0 017-2.5A4 4 0 0119 10c0 5.6-7 10-7 10z"/></svg>Favoritos</button>\n<button data-t="al"><svg viewBox="0 0 24 24"><path d="M6 16V11a6 6 0 0112 0v5l2 2H4z"/><path d="M10 21h4"/></svg>Alertas</button>\n<button data-t="top"><svg viewBox="0 0 24 24"><path d="M8 4h8v5a4 4 0 01-8 0z"/><path d="M8 6H4v1a4 4 0 004 4M16 6h4v1a4 4 0 01-4 4M12 13v4M8 20h8"/></svg>Top</button>\n</nav>\n<script>\nconst tg=window.Telegram&&Telegram.WebApp;if(tg){tg.ready();tg.expand();try{tg.setHeaderColor("#05030f");tg.setBackgroundColor("#05030f")}catch(e){}}\nconst hap=(k)=>{try{tg&&tg.HapticFeedback&&(k==="s"?tg.HapticFeedback.notificationOccurred("success"):tg.HapticFeedback.impactOccurred("light"))}catch(e){}};\nconst H={"X-Init":(tg&&tg.initData)||""};let ALL=[],MIN=0,FAV=new Set(),FAVL=[],CAT="Todas",VID=[];\nconst eur=n=>Number(n).toFixed(2).replace(".",",")+" €";\nconst esc=s=>String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",\'"\':"&quot;"}[c]));\nfunction ago(ts){const m=Math.max(1,Math.round((Date.now()/1000-ts)/60));return m<60?`hace ${m} min`:m<1440?`hace ${Math.round(m/60)} h`:`hace ${Math.round(m/1440)} d`}\nfunction card(o,i){const mins=(Date.now()/1000-o.ts)/60;const tags=(o.pct>=50?\'<span class="tag hot">🔥 CHOLLO</span>\':"")+(mins<30?\'<span class="tag new">NUEVA</span>\':"")+(o.cat?`<span class="tag">${esc(o.cat)}</span>`:"");\nreturn `<div class="card" style="animation-delay:${Math.min(i||0,8)*45}ms"><button class="hb${FAV.has(o.asin)?" on":""}" data-h="${esc(o.asin)}">${FAV.has(o.asin)?"♥":"♡"}</button><div class="tt">${esc(o.t)}</div><div class="row"><div class="now">${eur(o.ahora)}</div><div class="old">${eur(o.antes)}</div><div class="pct">-${o.pct}%</div></div><div class="bar"><i style="width:${Math.min(100,o.pct)}%"></i></div><div class="meta">${tags}<span class="sv">Ahorras ${eur(o.antes-o.ahora)}</span><span>· ${ago(o.ts)}</span></div><div class="two"><button class="btn" data-a="${esc(o.asin)}" data-u="${esc(o.url)}">Ver oferta</button><button class="btn sec" data-s="${esc(o.url)}" data-n="${esc(o.t)} a ${o.ahora} € (-${o.pct}%)">Compartir</button></div></div>`}\nfunction heroHtml(){const lim=Date.now()/1000-86400;const c=ALL.filter(o=>o.ts>=lim);if(!c.length)return"";const o=c.reduce((a,b)=>b.pct>a.pct?b:a);return `<div class="hero"><small>⭐ OFERTA ESTRELLA DE HOY</small><div class="bg">-${o.pct}%</div><div class="tt" style="margin-top:30px">${esc(o.t)}</div><div class="big">${eur(o.ahora)}<s>${eur(o.antes)}</s></div><button class="btn" data-a="${esc(o.asin)}" data-u="${esc(o.url)}">Ver oferta</button></div>`}\nfunction draw(){const q=document.getElementById("q").value.toLowerCase();let l=ALL.filter(o=>o.pct>=MIN&&o.t.toLowerCase().includes(q)&&(CAT==="Todas"||o.cat===CAT));const s=document.getElementById("ord").value;if(s==="d")l.sort((a,b)=>b.pct-a.pct);else if(s==="p")l.sort((a,b)=>a.ahora-b.ahora);document.getElementById("hero").innerHTML=heroHtml();document.getElementById("list").innerHTML=l.length?l.map(card).join(""):\'<div class="empty">Aún no hay ofertas con ese filtro.<br>Crea una alerta y te aviso al momento.</div>\';const cs=["Todas",...new Set(ALL.map(o=>o.cat).filter(Boolean))];document.getElementById("cats").innerHTML=cs.map(c=>`<button class="chip${c===CAT?" on":""}" data-c="${esc(c)}">${esc(c)}</button>`).join("")}\nfunction drawFav(){document.getElementById("favs").innerHTML=FAVL.length?FAVL.map(card).join(""):\'<div class="empty">Toca el corazón ♡ de una oferta para guardarla aquí.</div>\'}\nfunction drawVid(){const f=document.getElementById("feed");if(!VID.length){f.innerHTML=\'<div class="empty" style="padding-top:90px">Los vídeos de las mejores ofertas aparecerán aquí.<br>Vuelve en un rato 🎬</div>\';return}\nf.innerHTML=VID.map(v=>`<div class="vs"><div class="vbox"><video src="${esc(v.v)}" muted loop playsinline preload="metadata"></video><div class="pc">-${v.pct}%</div></div><div class="vinfo"><div class="tt">${esc(v.t)}</div><div class="row" style="margin-top:6px"><div class="now">${eur(v.ahora)}</div><div class="old">${eur(v.antes)}</div></div><div class="two"><button class="btn" data-a="${esc(v.asin)}" data-u="${esc(v.url)}">Ver oferta</button><button class="btn sec" data-s="${esc(v.url)}" data-n="${esc(v.t)} a ${v.ahora} € (-${v.pct}%)">Compartir</button></div></div></div>`).join("");\nconst io=new IntersectionObserver(es=>es.forEach(e=>{const vi=e.target.querySelector("video");if(!vi)return;if(e.isIntersecting&&e.intersectionRatio>.6){const p=vi.play();p&&p.catch(()=>{})}else vi.pause()}),{root:f,threshold:[.6]});f.querySelectorAll(".vs").forEach(x=>io.observe(x))}\nasync function post(p,b){const r=await fetch(p,{method:"POST",headers:{...H,"Content-Type":"application/json"},body:JSON.stringify(b)});return r.json().catch(()=>({}))}\nasync function loadFav(){try{const r=await fetch("/api/fav",{headers:H});if(!r.ok)return;const j=await r.json();FAVL=j.fav||[];FAV=new Set(FAVL.map(o=>o.asin));drawFav();draw()}catch(e){}}\nasync function loadVid(){try{const r=await fetch("/api/videos",{headers:H});const j=await r.json();VID=j.videos||[];drawVid()}catch(e){}}\nasync function loadAl(){try{const r=await fetch("/api/alertas",{headers:H});if(!r.ok){document.getElementById("als").innerHTML=\'<div class="empty">Abre la app desde el bot para usar las alertas.</div>\';return}const j=await r.json();document.getElementById("als").innerHTML=(j.al||[]).length?j.al.map((a,i)=>`<div class="al"><div>${a.q?esc(a.q):"Cualquier producto"} · ${a.min?a.min+"%+":"cualquier descuento"}</div><button data-d="${i}">✕</button></div>`).join(""):\'<div class="empty">Aún no tienes alertas.</div>\'}catch(e){}}\ndocument.addEventListener("click",async e=>{const hb=e.target.closest(".hb");if(hb){hb.classList.add("pop");hap();const r=await post("/api/fav",{asin:hb.dataset.h});if(r.ok){hap("s");loadFav()}return}const sh=e.target.closest("[data-s]");if(sh){const u="https://t.me/share/url?url="+encodeURIComponent(sh.dataset.s)+"&text="+encodeURIComponent(sh.dataset.n);tg?tg.openTelegramLink(u):window.open(u,"_blank");return}const ch=e.target.closest("[data-c]");if(ch){CAT=ch.dataset.c;hap();draw();return}const dl=e.target.closest("[data-d]");if(dl){await post("/api/alertas/del",{i:+dl.dataset.d});loadAl();return}const b=e.target.closest(".btn");if(!b||!b.dataset.a)return;hap();fetch("/api/click",{method:"POST",headers:{...H,"Content-Type":"application/json"},body:JSON.stringify({asin:b.dataset.a})}).catch(()=>{});tg?tg.openLink(b.dataset.u):window.open(b.dataset.u,"_blank")});\ndocument.getElementById("q").oninput=draw;document.getElementById("ord").onchange=draw;\ndocument.getElementById("aadd").onclick=async()=>{const q=document.getElementById("aq").value.trim(),m=+document.getElementById("am").value;if(!q&&m<50){alert("Escribe un producto o elige 50% o más.");return}const r=await post("/api/alertas",{q,min:m});if(!r.ok){alert(r.error||"No se pudo crear");return}hap("s");document.getElementById("aq").value="";loadAl()};\n[["Todas",0],["30%+",30],["50%+",50],["70%+",70]].forEach(([n,v])=>{const c=document.createElement("button");c.className="chip"+(v===0?" on":"");c.textContent=n;c.onclick=()=>{MIN=v;hap();document.querySelectorAll("#chips .chip").forEach(x=>x.classList.remove("on"));c.classList.add("on");draw()};document.getElementById("chips").appendChild(c)});\nconst TABS=["of","vd","fv","al","top","ad"];\nfunction go(t){document.querySelectorAll(".tabs button").forEach(x=>x.classList.toggle("on",x.dataset.t===t));TABS.forEach(x=>document.getElementById("t-"+x).classList.toggle("hide",x!==t));document.getElementById("legal").classList.toggle("hide",t==="vd");hap();if(t==="top")loadTop();if(t==="fv")loadFav();if(t==="al")loadAl();if(t==="vd")loadVid();if(t==="ad")loadAdmin();if(t!=="vd")document.querySelectorAll("video").forEach(v=>v.pause())}\ndocument.querySelectorAll(".tabs button").forEach(b=>b.onclick=()=>go(b.dataset.t));document.getElementById("adbtn").onclick=()=>go("ad");\nasync function load(){try{const r=await fetch("/api/ofertas",{headers:H});const j=await r.json();ALL=j.ofertas||[];if(j.admin)document.getElementById("adbtn").classList.remove("hide");document.getElementById("sub").textContent=ALL.length?`${ALL.length} ofertas recientes · en directo`:"Esperando nuevas ofertas";draw()}catch(e){document.getElementById("list").innerHTML=\'<div class="empty">No se pudo cargar. Inténtalo de nuevo.</div>\'}}\nasync function loadTop(){const r=await fetch("/api/top",{headers:H});const j=await r.json();document.getElementById("top").innerHTML=(j.descuento||[]).length?j.descuento.map(card).join(""):\'<div class="empty">Aún no hay datos.</div>\';document.getElementById("clk").innerHTML=(j.clicks||[]).length?j.clicks.map(c=>`<div class="card"><div class="tt">${esc(c.t)}</div><div class="meta">${c.n} pulsaciones</div></div>`).join(""):\'<div class="empty">Todavía nadie ha pulsado.</div>\'}\nasync function loadAdmin(){const r=await fetch("/api/admin",{headers:H});if(!r.ok)return;const j=await r.json();document.getElementById("stats").innerHTML=j.stats.map(s=>`<div class="st"><b>${esc(s[1])}</b><span>${esc(s[0])}</span></div>`).join("");document.getElementById("sws").innerHTML=j.toggles.map(t=>`<div class="sw"><div>${esc(t.nombre)}</div><button class="${t.on?"on":""}" data-k="${t.k}"></button></div>`).join("");document.querySelectorAll(".sw button").forEach(b=>b.onclick=async()=>{await fetch("/api/admin/toggle",{method:"POST",headers:{...H,"Content-Type":"application/json"},body:JSON.stringify({k:b.dataset.k})});loadAdmin()})}\nload();loadFav();setInterval(load,60000);\n</script></body></html>\n'

